let cur = 'en';
export function setLang(l) { cur = LANGS.includes(l) ? l : 'en'; document.documentElement.lang = cur === 'pt' ? 'pt-PT' : 'en'; }
export function lang() { return cur; }
export function t(key, vars) {
  let s = D[cur][key] ?? D.en[key] ?? key;
  if (vars) for (const k in vars) s = s.replaceAll('{' + k + '}', vars[k]);
  return s;
}
// texto com várias versões: escolhe uma pela semente (a mesma notícia diz sempre o mesmo)
export function tv(key, seed, vars) {
  const v = D[cur][key] ?? D.en[key];
  let s = Array.isArray(v) ? v[Math.abs(seed) % v.length] : (v ?? key);
  if (vars) for (const k in vars) s = s.replaceAll('{' + k + '}', vars[k]);
  return s;
}
export function list(key) { return D[cur][key] || D.en[key]; }
// os erros com valores («O lance mínimo é {min}.»): sem o valor, o texto sem números (CODE_0) ou o genérico
export function errText(code, data) {
  const s = D[cur].err[code] || D.en.err[code];
  if (!s) return D[cur].err.default;
  if (!s.includes('{')) return s;
  let ok = true;
  const out = s.replace(/\{(\w+)\}/g, (_, k) => { const v = data?.[k]; if (v === undefined || v === null) { ok = false; return ''; } return String(v); });
  return ok ? out : D[cur].err[code + '_0'] || D.en.err[code + '_0'] || D[cur].err.default;
}
export function guessLang() {
  try { const s = localStorage.getItem('cr.lang'); if (s) return s; } catch {}
  return (navigator.language || '').toLowerCase().startsWith('pt') ? 'pt' : 'en';
}
